        }
    }
}

// Persistent identity DATA is separate from strictly expiring JWT claims.
use gateway_source::js_string::JsString16;
use serde::{Deserialize, Serialize};

pub const PASSPORT_COOKIE_MAX_AGE_SECONDS: i64 = 400 * 24 * 60 * 60;
pub const PASSPORT_VERIFIER_COOKIE: &str = "__Host-uos_ai_passport_verifier";
pub const PASSPORT_SESSION_URL: &str = "https://passport.ubq.fi/api/auth/sso/session";
pub const PASSPORT_REVOKE_URL: &str = "https://passport.ubq.fi/api/auth/sso/session/revoke";

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct PassportSessionIdentity {
    pub subject: JsString16,
    pub handle: JsString16,
    #[serde(rename = "isAdmin")]
    pub is_admin: bool,
    pub scopes: Vec<JsString16>,
}

/// The source's Date.parse primitive. Returns NaN for invalid dates, never a
/// policy decision or proof. Production JS hosts must use their actual engine.
pub trait PassportDate {
    fn parse_date_ms(&self, value: &JsString16) -> f64;
}

/// Source JWT DATA. Expiration stays mandatory; this is never a persistent SSO
/// record and there is no public authenticity constructor.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PassportSourceClaims {
    pub iss: String,
    pub sub: JsString16,
    #[serde(default)]
    pub handle: JsString16,
    pub is_admin: bool,
    #[serde(default)]
    pub scopes: Vec<JsString16>,
    pub aud: String,
    pub client_id: String,
    pub auth: JsString16,
    pub iat: i64,
    pub exp: i64,
    pub jti: JsString16,
    #[serde(default)]
    pub agent_token_id: Option<JsString16>,
}
impl PassportSourceClaims {
    pub fn valid(&self, now: i64) -> bool {
        self.valid_for(&crate::passport::PassportConfig::production(), now)
    }
    pub fn valid_for(&self, config: &crate::passport::PassportConfig, now: i64) -> bool {
        let bound = |value: &JsString16, max, empty| {
            (empty || !value.as_units().is_empty()) && value.as_units().len() <= max
        };
        let safe = gateway_core::identity::MAX_SAFE_INTEGER;
        self.iss == "https://passport.ubq.fi"
            && self.aud == config.audience
            && self.client_id == config.client_id
            && bound(&self.sub, 500, false)
            && bound(&self.jti, 500, false)
            && bound(&self.auth, 160, false)
            && bound(&self.handle, 500, true)
            && self.scopes.len() <= 128
            && self.scopes.iter().all(|scope| bound(scope, 500, true))
            && (-safe..=safe).contains(&self.iat)
            && (-safe..=safe).contains(&self.exp)
            && self.exp > now
            && self.exp > self.iat
            && self.iat <= now.saturating_add(60)
            && self
                .agent_token_id
                .as_ref()
                .is_none_or(|id| bound(id, 500, false))
    }
}

/// JSON.parse after TextDecoder's replacement/BOM behavior, followed by the
/// existing lossless JS JSON normalization (including last duplicate fields).
pub fn parse_source_json(
    bytes: &[u8],
) -> Result<gateway_source::source_json::SourceJson, gateway_source::error::GatewayError> {
    let text = String::from_utf8_lossy(bytes);
    let value = gateway_source::source_json::SourceJson::parse(
        text.strip_prefix('\u{feff}').unwrap_or(&text),
    )?;
    gateway_source::source_serialization::canonical(&value)
}

impl PassportSourceClaims {
    /// Historical scalar DATA conversion only; never the new authentication parser.
    pub fn from_legacy(value: crate::passport::PassportClaims) -> Self {
        Self {
            iss: value.iss,
            sub: JsString16::from_utf8(&value.sub),
            handle: JsString16::from_utf8(&value.handle),
            is_admin: value.is_admin,
            scopes: value
                .scopes
                .iter()
                .map(|v| JsString16::from_utf8(v))
                .collect(),
            aud: value.aud,
            client_id: value.client_id,
            auth: JsString16::from_utf8(&value.auth),
            iat: value.iat,
            exp: value.exp,
            jti: JsString16::from_utf8(&value.jti),
            agent_token_id: value.agent_token_id.as_deref().map(JsString16::from_utf8),
        }
    }
    /// Explicit legacy serde boundary. Source authentication must retain self's units.
    pub fn try_legacy_scalar(
        &self,
    ) -> Result<crate::passport::PassportClaims, gateway_source::error::GatewayError> {
        Ok(crate::passport::PassportClaims {
            iss: self.iss.clone(),
            sub: self.sub.try_utf8()?,
            handle: self.handle.try_utf8()?,
            is_admin: self.is_admin,
            scopes: self
                .scopes
                .iter()
                .map(JsString16::try_utf8)
                .collect::<Result<_, _>>()?,
            aud: self.aud.clone(),
            client_id: self.client_id.clone(),
            auth: self.auth.try_utf8()?,
            iat: self.iat,
            exp: self.exp,
            jti: self.jti.try_utf8()?,
            agent_token_id: self
                .agent_token_id
                .as_ref()
                .map(JsString16::try_utf8)
                .transpose()?,
        })
    }
}

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use url::Url;
pub const PASSPORT_ISSUER: &str = "https://passport.ubq.fi";
pub const PASSPORT_AUTHORIZE_URL: &str = "https://passport.ubq.fi/authorize";
pub const PASSPORT_EXCHANGE_URL: &str = "https://passport.ubq.fi/api/auth/sso/exchange";
pub const PASSPORT_JWKS_URL: &str = "https://passport.ubq.fi/api/auth/jwks";
pub const PASSPORT_PRODUCTION_CLIENT_ID: &str = "ai";
pub const PASSPORT_PRODUCTION_AUDIENCE: &str = "ai";
pub const PASSPORT_PRODUCTION_ORIGIN: &str = "https://ai.ubq.fi";
pub const PASSPORT_PRODUCTION_REDIRECT_URI: &str = "https://ai.ubq.fi/auth/callback";
pub const PASSPORT_COOKIE: &str = "__Host-uos_ai_passport_session";
pub const PASSPORT_STATE_COOKIE: &str = "__Host-uos_ai_passport_state";
pub const PASSPORT_STATE_TTL_SECONDS: i64 = 600;
pub const PASSPORT_JWKS_CACHE_MS: i64 = 300_000;
pub const PASSPORT_JWKS_MAX_BYTES: usize = 262_144;
pub const PASSPORT_EXCHANGE_MAX_BYTES: usize = 65_536;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PassportConfig {
    pub client_id: String,
    pub audience: String,
    pub origin: String,
    pub redirect_uri: String,
}

impl PassportConfig {
    pub fn production() -> Self {
        Self {
            client_id: PASSPORT_PRODUCTION_CLIENT_ID.into(),
            audience: PASSPORT_PRODUCTION_AUDIENCE.into(),
            origin: PASSPORT_PRODUCTION_ORIGIN.into(),
            redirect_uri: PASSPORT_PRODUCTION_REDIRECT_URI.into(),
        }
    }

    /// Explicit preview registration only. Partial or non-HTTPS values disable
    /// browser login rather than silently reusing the production `ai` client.
    pub fn from_values(values: &BTreeMap<String, String>) -> Option<Self> {
        let value = |name: &str| {
            values
                .get(name)
                .map(|value| value.trim())
                .filter(|value| !value.is_empty())
        };
        let client_id = value("UOS_AI_PASSPORT_CLIENT_ID")?;
        let audience = value("UOS_AI_PASSPORT_AUDIENCE").unwrap_or(PASSPORT_PRODUCTION_AUDIENCE);
        let origin = value("UOS_AI_PASSPORT_ORIGIN")?;
        let redirect_uri = value("UOS_AI_PASSPORT_REDIRECT_URI")?;
        if !valid_https_origin(origin) || client_id.len() > 120 || audience.len() > 160 {
            return None;
        }
        let redirect = Url::parse(redirect_uri).ok()?;
        if redirect.scheme() != "https"
            || redirect.origin().ascii_serialization() != origin.trim_end_matches('/')
            || redirect.query().is_some()
            || redirect.fragment().is_some()
        {
            return None;
        }
        Some(Self {
            client_id: client_id.into(),
            audience: audience.into(),
            origin: origin.trim_end_matches('/').into(),
            redirect_uri: redirect_uri.into(),
        })
    }
}

fn valid_https_origin(value: &str) -> bool {
    let Ok(url) = Url::parse(value) else {
        return false;
    };
    url.scheme() == "https"
        && url.port().is_none()
        && url.host_str().is_some()
        && url.path() == "/"
        && url.query().is_none()
        && url.fragment().is_none()
        && url.origin().ascii_serialization() == value.trim_end_matches('/')
}

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub struct PassportClaims {
    pub iss: String,
    pub sub: String,
    #[serde(default)]
    pub handle: String,
    #[serde(rename = "isAdmin")]
    pub is_admin: bool,
    #[serde(default)]
    pub scopes: Vec<String>,
    pub aud: String,
    #[serde(rename = "clientId")]
    pub client_id: String,
    pub auth: String,
    pub iat: i64,
    pub exp: i64,
    pub jti: String,
    #[serde(
        rename = "agentTokenId",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub agent_token_id: Option<String>,
}

impl PassportClaims {
    pub fn valid(&self, config: &PassportConfig, now_seconds: i64) -> bool {
        self.iss == PASSPORT_ISSUER
            && self.aud == config.audience
            && self.client_id == config.client_id
            && !self.sub.is_empty()
            && self.sub.encode_utf16().count() <= 500
            && !self.jti.is_empty()
            && self.jti.encode_utf16().count() <= 500
            && !self.auth.is_empty()
            && self.auth.encode_utf16().count() <= 160
            && self.handle.encode_utf16().count() <= 500
            && self.scopes.len() <= 128
            && self
                .scopes
                .iter()
                .all(|scope| scope.encode_utf16().count() <= 500)
            && (-gateway_core::identity::MAX_SAFE_INTEGER
                ..=gateway_core::identity::MAX_SAFE_INTEGER)
                .contains(&self.iat)
            && (-gateway_core::identity::MAX_SAFE_INTEGER
                ..=gateway_core::identity::MAX_SAFE_INTEGER)
                .contains(&self.exp)
            && self.exp > now_seconds
            && self.iat <= now_seconds.saturating_add(60)
            && self.exp > self.iat
            && self
                .agent_token_id
                .as_ref()
                .is_none_or(|id| !id.is_empty() && id.encode_utf16().count() <= 500)
    }
}

