    redirect_uri: String,
    created_at: JsString16,
    token: String,
}
impl Grant {
    fn record(self) -> Record {
        Record {
            version: 1.0,
            subject: self.subject,
            client_id: self.client_id,
            audience: self.audience,
            origin: self.origin,
            redirect_uri: self.redirect_uri,
            created_at: self.created_at,
