pub fn mapping_key(call_id: &str) -> RecordKey {
    TupleKey::from_scalar_parts(&[
        ScalarKeyPart::String("uos_ai"),
        ScalarKeyPart::String("codex_live_calls"),
        ScalarKeyPart::String("v1"),
        ScalarKeyPart::String(call_id),
    ])
    .to_record_key()
}

/// Private control custody, retained until known mapping deletion. M20 must preserve this marker.
pub fn retirement_key(call_id: &str) -> RecordKey {
    TupleKey::from_scalar_parts(&[
        ScalarKeyPart::String("uos_ai"),
        ScalarKeyPart::String("codex_live_calls"),
        ScalarKeyPart::String("v1"),
        ScalarKeyPart::String("pending_retirement"),
        ScalarKeyPart::String(call_id),
    ])
    .to_record_key()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RetirementOutcome {
    NotTerminal,
    Retired,
    /// Marker persists; originating operation retries at250ms only while actually alive.
    Pending,
    /// Storage cannot establish the effect. Never label this retired or clear the local guard.
    Unknown,
}

/// Minted ONLY with a prepared authorized sideband. No public constructor or serde implementation.
pub struct Retirement<S> {
    pub(crate) runtime: LiveRuntime<S>,
    pub(crate) call_id: String,
}

impl<S: AuthorityStore> Retirement<S> {
    /// The trusted physical bridge calls this only for its ACTUAL upstream handshake response.
    pub async fn on_handshake_rejection(&self, status: u16, now_ms: i64) -> RetirementOutcome {
        if status != 404 && status != 410 {
            return RetirementOutcome::NotTerminal;
        }
        self.runtime
            .state
            .pending
            .borrow_mut()
            .entry(self.call_id.clone())
            .or_insert(Pending {
                status,
                created_at_ms: now_ms,
            });
        self.runtime.retire_once(&self.call_id).await
    }

    pub async fn retry_once(&self) -> RetirementOutcome {
        self.runtime.retire_once(&self.call_id).await
    }
}

impl<S: AuthorityStore> LiveRuntime<S> {
    fn revision(&self) -> Result<String, GatewayError> {
        let revision = (self.state.next_revision)()?;
        if revision.is_empty() {
            return Err(GatewayError::unavailable(
                "Live state revision is unavailable.",
                "live_revision_unavailable",
            ));
        }
        Ok(revision)
    }

    /// The injected store is the SAME existing authority, never a new live ledger.
    pub fn new(store: Rc<S>, next_revision: Rc<dyn Fn() -> Result<String, GatewayError>>) -> Self {
        Self {
            state: Rc::new(State {
                store,
                next_revision,
                pending: RefCell::new(BTreeMap::new()),
            }),
        }
    }

    pub(crate) async fn write_mapping(
        &self,
        call_id: &str,
        account: &str,
        principal: &JsString16,
        now: i64,
    ) {
        // Deliberately best-effort and unconditional. Never clears a pending-retirement marker.
        let Ok(revision) = self.revision() else {
            return;
        };
        let Ok(record) = encode_mapping(revision, account, principal, now) else {
            return;
        };
        let _ = self
            .state
            .store
            .commit(AtomicTransition {
                checks: vec![],
                mutations: vec![RecordMutation::Put {
                    key: mapping_key(call_id),
                    record,
                }],
            })
            .await;
    }

    pub(crate) async fn read_mapping(&self, call_id: &str, now: i64) -> Option<Mapping> {
        let marker = self.state.store.read(&retirement_key(call_id)).await.ok()?;
        if marker.is_some() || self.state.pending.borrow().contains_key(call_id) {
            // Related authenticated request event resumes ONE step; no background scheduler.
            self.retire_once(call_id).await;
            return None;
        }
        let record = self.state.store.read(&mapping_key(call_id)).await.ok()??;
        // Suppress a retirement started while the mapping read was awaiting, also after restart.
        if self.state.pending.borrow().contains_key(call_id)
            || self
                .state
                .store
                .read(&retirement_key(call_id))
                .await
                .ok()?
                .is_some()
        {
            return None;
        }
        if record.expires_at_ms.is_some_and(|expiry| expiry <= now) {
            return None;
        }
        decode_mapping(&record)
    }

    async fn retire_once(&self, call_id: &str) -> RetirementOutcome {
        let key = retirement_key(call_id);
        let mut marker = match self.state.store.read(&key).await {
            Ok(value) => value,
            Err(_) => return RetirementOutcome::Unknown,
        };
        if let Some(record) = marker.as_ref() {
            let Some(pending) = parse_marker(record, call_id) else {
                return RetirementOutcome::Unknown;
            };
            self.state
                .pending
                .borrow_mut()
                .insert(call_id.into(), pending);
        } else {
            let Some(pending) = self.state.pending.borrow().get(call_id).cloned() else {
                return RetirementOutcome::NotTerminal;
            };
            let Ok(revision) = self.revision() else {
                return RetirementOutcome::Unknown;
            };
            let record = StoredRecord::json(
                revision,
                json!({"schema_version":1,"call_id":call_id,"upstream_status":pending.status,"created_at_ms":pending.created_at_ms}),
                None,
            );
            match self
                .state
                .store
                .commit(AtomicTransition {
                    checks: vec![],
                    mutations: vec![RecordMutation::Put {
                        key: key.clone(),
                        record,
                    }],
                })
                .await
            {
                Ok(CommitOutcome::Committed) => {}
                Ok(CommitOutcome::Conflict) => return RetirementOutcome::Pending,
                Err(_) => return RetirementOutcome::Unknown,
            }
            marker = match self.state.store.read(&key).await {
                Ok(Some(record)) => Some(record),
                _ => return RetirementOutcome::Unknown,
            };
        }
        // Source deletion remains unconditional, not a join claim or a mapping revision lease.
        match self
            .state
            .store
            .commit(AtomicTransition {
                checks: vec![],
                mutations: vec![RecordMutation::Delete {
                    key: mapping_key(call_id),
                }],
            })
            .await
        {
            Ok(CommitOutcome::Committed) => {}
            Ok(CommitOutcome::Conflict) => return RetirementOutcome::Pending,
            Err(_) => return RetirementOutcome::Unknown,
        }
        // Clear only after known successful deletion. A concurrent reused ID or newer terminal
        // marker retains suppression instead of clearing another operation's control record.
        let marker = marker.expect("marker was read after a successful write or existed");
        match self
            .state
            .store
            .commit(AtomicTransition {
                checks: vec![
                    RevisionCheck {
                        key: mapping_key(call_id),
                        expected_revision: None,
                    },
                    RevisionCheck {
                        key: key.clone(),
                        expected_revision: Some(marker.revision),
                    },
                ],
                mutations: vec![RecordMutation::Delete { key }],
            })
            .await
        {
            Ok(CommitOutcome::Committed) => {
                self.state.pending.borrow_mut().remove(call_id);
                RetirementOutcome::Retired
            }
            Ok(CommitOutcome::Conflict) => RetirementOutcome::Pending,
            Err(_) => RetirementOutcome::Unknown,
        }
    }
}

fn parse_marker(record: &StoredRecord, call_id: &str) -> Option<Pending> {
    let value = record.json_value().ok()?;
    if value.get("schema_version")?.as_u64()? != 1 || value.get("call_id")?.as_str()? != call_id {
        return None;
    }
    let status = u16::try_from(value.get("upstream_status")?.as_u64()?).ok()?;
    matches!(status, 404 | 410).then_some(Pending {
        status,
        created_at_ms: value.get("created_at_ms")?.as_i64()?,
    })
}

pub(crate) fn mapping_missing() -> GatewayError {
    crate::types::invalid(404, "Unknown realtime call.")
}

/// Mapping DATA only. Other fields retain their scalar domains and original expiry.
fn encode_mapping(
    revision: String,
    account: &str,
    principal: &JsString16,
    now: i64,
) -> Result<StoredRecord, GatewayError> {
    #[derive(Serialize)]
    struct Data<'a> {
        account_id: &'a str,
        principal_id: &'a JsString16,
        created_at_ms: i64,
    }
    let source = SourceJson::from_serializable(&Data {
        account_id: account,
        principal_id: principal,
        created_at_ms: now,
    })?;
    source_control::encode_source_control_record(
        revision,
        &source,
        Some(now.saturating_add(LIVE_CALL_ACCOUNT_TTL_MS)),
    )
}
fn decode_mapping(record: &StoredRecord) -> Option<Mapping> {
    let value = source_control::decode_source_control_record(record).ok()?;
    Some(Mapping {
        account_id: source::member(&value, "account_id")?
            .deserialize::<String>()
            .ok()?,
        // Source getString accepts every string, including empty. Non-string/absent stays null.
        principal_id: source::member(&value, "principal_id").and_then(|v| source::string(&v)),
    })
}

#[cfg(test)]
mod passport_data_cases {
    use super::{decode_mapping, encode_mapping};
    use gateway_core::state::StoredRecord;
    use gateway_core::value::ValueEncoding;
    use gateway_source::js_string::JsString16;

    #[test]
    fn mapping_codec_preserves_exact_identity_units_and_scalar_history()
    -> Result<(), Box<dyn std::error::Error>> {
        for units in [
            vec![],
            vec![112, 0, 0xd800, 0xdfff],
            "ordinary".encode_utf16().collect(),
        ] {
            let principal = JsString16::from_units(units);
            let row = encode_mapping("revision".into(), "account", &principal, 100)?;
            let decoded = decode_mapping(&row).ok_or("mapping codec refused its valid output")?;
            assert_eq!(decoded.account_id, "account");
            assert_eq!(decoded.principal_id, Some(principal.clone()));
            assert_eq!(
                row.expires_at_ms,
                Some(100 + crate::types::LIVE_CALL_ACCOUNT_TTL_MS)
            );
            assert_eq!(row.revision, "revision");
            assert_eq!(
                row.value_encoding,
                if principal.try_utf8().is_ok() {
                    ValueEncoding::Json
                } else {
                    ValueEncoding::ProfileV2
                }
            );
        }
        for value in [
            serde_json::json!({"account_id":"account"}),
            serde_json::json!({"account_id":"account","principal_id":false}),
            serde_json::json!({"account_id":"account","principal_id":null}),
        ] {
            assert!(
                decode_mapping(&StoredRecord::json("revision", value, None))
                    .ok_or("legacy mapping")?
                    .principal_id
                    .is_none()
            );
        }
        let scalar = encode_mapping("r".into(), "account", &JsString16::from_utf8("p"), 100)?;
        assert_eq!(
            serde_json::to_string(scalar.json_value()?)?,
            r#"{"account_id":"account","principal_id":"p","created_at_ms":100}"#
        );
        Ok(())
    }
}

use crate::types::*;
use gateway_auth::types::{AuthMethod, AuthPrincipal};
use gateway_core::{error::GatewayError, js_string::JsString16, source_json::SourceJson};
use std::collections::BTreeMap;

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum LiveRoute {
    Create,
    Sideband(String),
}

pub fn live_route(method: &str, path: &str) -> Option<LiveRoute> {
    let path = if path == "/" {
        path
    } else {
        path.trim_end_matches('/')
    };
    if method == "POST" && path == "/v1/live" {
        return Some(LiveRoute::Create);
    }
    let raw = path.strip_prefix("/v1/live/")?;
    if method != "GET" || raw.contains('/') {
        return None;
    }
    let bytes = raw.as_bytes();
    let mut decoded = Vec::new();
    let mut at = 0;
    while at < bytes.len() {
        if bytes[at] == b'%' {
            let value = u8::from_str_radix(raw.get(at + 1..at + 3)?, 16).ok()?;
            decoded.push(value);
            at += 3;
        } else {
            decoded.push(bytes[at]);
            at += 1;
        }
    }
    let id = String::from_utf8(decoded).ok()?;
    (!matches!(id.as_str(), "" | "." | "..")).then_some(LiveRoute::Sideband(id))
}

pub fn encode_call_id(id: &str) -> String {
    let mut result = String::new();
    for byte in id.bytes() {
        if byte.is_ascii_alphanumeric() || b"-_.!~*'()".contains(&byte) {
            result.push(char::from(byte));
        } else {
            result.push_str(&format!("%{byte:02X}"));
        }
    }
    result
}

pub fn call_id_from_location(location: &str) -> Option<String> {
    location
        .split('?')
        .next()?
        .split('/')
        .rev()
        .find_map(|part| {
            let uuid = part.len() == 36
                && part.bytes().enumerate().all(|(i, c)| {
                    if [8, 13, 18, 23].contains(&i) {
                        c == b'-'
                    } else {
                        c.is_ascii_hexdigit()
                    }
                });
            ((part.starts_with("rtc_") && part.len() > 4) || uuid).then(|| part.to_owned())
        })
}

pub fn principal_id(principal: &AuthPrincipal) -> gateway_core::identity::PrincipalId {
    let scalar = match &principal.method {
        AuthMethod::KvApiKey { key_id, .. } => format!("api-key:{key_id}"),
        AuthMethod::GithubToken { owner, repo, .. } => format!(
            "github-repo:{}/{}",
            owner.to_lowercase(),
            repo.to_lowercase()
        ),
        AuthMethod::PasskeySession { user_id, .. } => format!("passkey-user:{user_id}"),
        AuthMethod::PassportSession { .. } | AuthMethod::PassportBearer { .. } => {
            return principal.method.principal_id(None);
        }
        AuthMethod::AuthTokensAllowlist => "auth-method:auth_tokens_allowlist".into(),
        AuthMethod::AdminAllowlist => "auth-method:admin_allowlist".into(),
        AuthMethod::DenoDeployToken => "auth-method:deno_deploy_token".into(),
        AuthMethod::Disabled => principal
            .token
            .as_ref()
            .map(|t| {
                format!(
                    "bearer-sha256:{}",
                    gateway_auth::crypto::sha256_hex(t.expose().as_bytes())
                )
            })
            .unwrap_or_else(|| "local-auth-disabled".into()),
    };
    gateway_core::identity::PrincipalId::from_scalar(scalar)
}

/// Source Content-Length canonicality is checked before any actual body read.
pub fn validate_declared_length(value: Option<&str>) -> Result<(), GatewayError> {
    let Some(value) = value else { return Ok(()) };
    let value = value.trim();
    if value.is_empty()
        || !value.bytes().all(|b| b.is_ascii_digit())
        || (value.starts_with('0') && value.len() > 1)
    {
        return Err(invalid(
            400,
            "Live call creation Content-Length is invalid.",
        ));
    }
    if value
        .parse::<u64>()
        .ok()
        .is_none_or(|n| n > LIVE_CALL_MAX_BODY_BYTES as u64)
    {
        return Err(body_too_large());
    }
    Ok(())
}

pub fn validate_body_read(bytes: usize, complete: bool) -> Result<(), GatewayError> {
    if bytes > LIVE_CALL_MAX_BODY_BYTES {
        return Err(body_too_large());
    }
    if !complete {
        return Err(invalid(
            400,
            "Live call creation body could not be read completely.",
        ));
    }
    Ok(())
}

fn body_too_large() -> GatewayError {
    invalid(
        413,
        "Live call creation bodies must be no larger than 1048576 bytes.",
    )
}

pub(crate) fn parse_create(
    input: &LiveCreateInput,
) -> Result<(SourceJson, Option<JsString16>), GatewayError> {
    let media = input.content_type.split(';').next().unwrap_or("").trim();
    if !media.eq_ignore_ascii_case("multipart/form-data")
        || !input
            .content_type
            .to_ascii_lowercase()
            .contains("boundary=")
    {
        return Err(invalid(
            400,
            "Live call creation requires multipart/form-data with a declared boundary.",
        ));
    }
    let sdp = input
        .sdp
        .as_ref()
        .filter(|s| !s.is_empty())
        .ok_or_else(|| {
            invalid(400, "Live call creation requires a non-empty `sdp` part.")
                .with_param(Some("sdp"))
        })?;
    let text = input.session.as_ref().ok_or_else(|| {
        invalid(400, "Live call creation requires a `session` part.").with_param(Some("session"))
    })?;
    let session = SourceJson::parse(text.trim()).map_err(|_| {
        invalid(400, "Live call creation `session` part must be valid JSON.")
            .with_param(Some("session"))
    })?;
    let entries = session.object_entries().map_err(|_| {
        invalid(
            400,
            "Live call creation `session` part must be a JSON object.",
        )
        .with_param(Some("session"))
    })?;
    let model = entries
        .iter()
        .rev()
        .find(|(key, _)| key == &JsString16::from_utf8("model"))
        .and_then(|(_, v)| JsString16::from_json_token(v.as_raw()).ok());
    let normalized = normalize_json(&session)?;
    let body = SourceJson::parse(&format!(
        "{{\"sdp\":{},\"session\":{normalized}}}",
        serde_json::to_string(sdp).expect("SDP string serializes")
    ))?;
    Ok((body, model))
}

/// Match JSON.parse/stringify: last duplicate wins, source object key order, JS number precision,
/// infinity->null and -0->0. String code units never pass through serde_json::Value.
fn normalize_json(raw: &SourceJson) -> Result<String, GatewayError> {
    let text = raw.as_str().trim();
    if text.starts_with('{') {
        let mut members: Vec<(JsString16, SourceJson)> = Vec::new();
        for (key, value) in raw.object_entries()? {
            if let Some((_, previous)) = members.iter_mut().find(|(existing, _)| existing == &key) {
                *previous = value;
            } else {
                members.push((key, value));
            }
        }
        fn index(key: &JsString16) -> Option<u32> {
            let text = key.try_utf8().ok()?;
            let n = text.parse::<u32>().ok()?;
            (n != u32::MAX && n.to_string() == text).then_some(n)
        }
        members.sort_by_key(|(key, _)| index(key).map_or((1, 0), |n| (0, n)));
        let entries = members
            .iter()
            .map(|(k, v)| {
                Ok(format!(
                    "{}:{}",
                    serde_json::to_string(k).expect("source string serializes"),
                    normalize_json(v)?
                ))
            })
            .collect::<Result<Vec<_>, GatewayError>>()?;
        return Ok(format!("{{{}}}", entries.join(",")));
    }
    if text.starts_with('[') {
        let values = raw
            .array_items()?
            .iter()
            .map(normalize_json)
            .collect::<Result<Vec<_>, _>>()?;
        return Ok(format!("[{}]", values.join(",")));
    }
    if text.starts_with('"') || matches!(text, "null" | "true" | "false") {
        return Ok(text.into());
    }
    let number = text
        .parse::<f64>()
        .map_err(|_| invalid(400, "Invalid session JSON number."))?;
    if !number.is_finite() {
        return Ok("null".into());
    }
    Ok(ryu_js::Buffer::new().format(number).into())
}

pub(crate) fn create_headers(
    input: &LiveCreateInput,
    user_agent: String,
) -> BTreeMap<String, String> {
    let mut headers = BTreeMap::from([
        ("content-type".into(), "application/json".into()),
        ("originator".into(), "codex_cli_rs".into()),
        ("user-agent".into(), user_agent),
        ("openai-alpha".into(), LIVE_OPENAI_ALPHA_DEFAULT.into()),
    ]);
    for name in [
        "openai-alpha",
        "x-session-id",
        "session-id",
        "thread-id",
        "x-codex-turn-metadata",
        "x-oai-attestation",
    ] {
        if let Some(value) = input.headers.get(name).filter(|v| !v.trim().is_empty()) {
            headers.insert(name.into(), value.clone());
        }
    }
    headers
}

//! Auth-only fixed transport. Preserve PlatformHost's actual cancellation and
//! store; bounds here apply only to new Passport app-session operations.
use crate::{
    host::{PlatformHost, response_bytes},
    transport::outbound::{Cancellation, PinnedDestination, send_http},
};
use gateway_auth_contracts::upstream::{AuthUpstreamRequest, AuthUpstreamResponse};
use gateway_auth_passport_contracts::session::PassportDate;
use gateway_source::{error::GatewayError, js_string::JsString16};
use std::{cell::Cell, collections::BTreeMap, task::Poll};
use worker::{
    Method, ResponseBody,
    js_sys::{Function, JsString, Reflect},
    wasm_bindgen::{JsCast, JsValue},
};

impl PassportDate for PlatformHost {
    fn parse_date_ms(&self, value: &JsString16) -> f64 {
        // Date::parse(&str) narrows the source domain before the actual JS
        // primitive. Pass a JS UTF16 string directly to Date.parse instead.
        let parsed = (|| {
            let date = Reflect::get(&worker::js_sys::global(), &JsValue::from_str("Date")).ok()?;
            let parse = Reflect::get(&date, &JsValue::from_str("parse"))
                .ok()?
                .dyn_into::<Function>()
                .ok()?;
            parse
                .call1(&date, &JsString::from_char_code(value.as_units()))
                .ok()?
                .as_f64()
        })();
        parsed.unwrap_or(f64::NAN)
    }
}

pub async fn fetch(
    host: &PlatformHost,
    request: AuthUpstreamRequest,
) -> Result<AuthUpstreamResponse, GatewayError> {
    if !request.app_session_operation() {
        return fetch_inner(
            request,
            &host.cancellation,
            4 * 1024 * 1024,
            &Cell::new(false),
        )
        .await;
    }
    // Local logout has already committed. Its best-effort upstream revoke is
    // independent of caller cancellation; other operations retain the caller.
    let cancellation = if matches!(request, AuthUpstreamRequest::PassportRevoke { .. }) {
        Cancellation::background()?
    } else {
        host.cancellation.child()?
    };
    let _deadline = cancellation.set_timeout_ms(10_000)?;
    let rejected = Cell::new(false);
    let operation = Box::pin(fetch_inner(request, &cancellation, 65_536, &rejected));
    let interrupted = Box::pin(std::future::poll_fn(|cx| {
        cancellation.register_waker(cx.waker());
        if cancellation.signal().aborted() {
            Poll::Ready(())
        } else {
            Poll::Pending
        }
    }));
    let result = match futures_util::future::select(operation, interrupted).await {
        futures_util::future::Either::Left((result, _)) => result,
        // A rejected body cannot hide an already observed authoritative 401,
        // including when cancellation itself stalls until the deadline.
        futures_util::future::Either::Right(_) if rejected.get() => Ok(AuthUpstreamResponse {
            status: 401,
            body: Vec::new(),
        }),
        futures_util::future::Either::Right(_) => Err(unavailable()),
    };
    if result.is_err() {
        cancellation.abort();
    }
    result
}
async fn fetch_inner(
    request: AuthUpstreamRequest,
    cancellation: &Cancellation,
    limit: usize,
    rejected: &Cell<bool>,
) -> Result<AuthUpstreamResponse, GatewayError> {
    let headers = request.headers().into_iter().collect::<BTreeMap<_, _>>();
    let destination = PinnedDestination::new(&request.url())?;
    let method = if request.method() == "POST" {
        Method::Post
    } else {
        Method::Get
    };
    let mut response = send_http(
        &destination,
        method,
        &headers,
        &request.body()?,
        cancellation,
        || async { Ok(()) },
    )
    .await
    .map_err(|failure| failure.error)?;
    let status = response.status_code();
    if matches!(request, AuthUpstreamRequest::PassportPkceExchange { .. })
        && matches!(response.body(), ResponseBody::Empty)
    {
        return Err(GatewayError::new(
            502,
            "Passport verification is unavailable.",
            Some("passport_exchange_body_missing"),
        ));
    }
    if request.status_only(status) {
        rejected
            .set(matches!(request, AuthUpstreamRequest::PassportSession { .. }) && status == 401);
        let raw: worker::web_sys::Response = response.into();
        let cancelled = if let Some(body) = raw.body() {
            worker::wasm_bindgen_futures::JsFuture::from(body.cancel())
                .await
                .map(|_| ())
        } else {
            Ok(())
        };
        if matches!(request, AuthUpstreamRequest::PassportRevoke { .. }) {
            cancelled.map_err(|_| unavailable())?;
        }
        return Ok(AuthUpstreamResponse {
            status,
            body: Vec::new(),
        });
    }
    Ok(AuthUpstreamResponse {
        status,
        body: response_bytes(&mut response, limit).await?,
    })
}
fn unavailable() -> GatewayError {
    GatewayError::new(
        503,
        "Passport session verification is unavailable.",
        Some("passport_unavailable"),
    )
}
